// Small is narrow, so its titles wrap to a second line and it shows one row fewer. Medium keeps one line.
function row(item, lines) {
  const toggle = { type: 'button', action: 'toggle', rowId: item.id, children: [
    { type: 'symbol', name: item.done ? 'checkmark.circle.fill' : 'circle', size: 16,
      color: item.done ? '#7AE582' : '#9FB3C8', frame: { width: 22, height: 22 } } ] };

  const remove = item.done && { type: 'button', action: 'remove', rowId: item.id, children: [
    { type: 'symbol', name: 'xmark', size: 11, weight: 'bold', color: '#9FB3C8',
      frame: { width: 22, height: 22 } } ] };

  return { type: 'hstack', spacing: 6, children: [
    toggle,
    { type: 'text', value: item.title || 'Untitled', size: lines > 1 ? 12 : 13, lineLimit: lines,
      color: item.done ? '#9FB3C8' : '#FFFFFF', strikethrough: item.done,
      frame: { maxWidth: 'infinity', alignment: 'leading' } },
    remove,
  ] };
}

function render(ctx) {
  const d = ctx.data;
  const small = ctx.family === 'small';
  const shown = d.open.concat(d.done).slice(0, small ? 3 : 4);

  const total = d.left + d.finished;
  const header = { type: 'hstack', spacing: 6, children: [
    { type: 'hstack', spacing: 6, frame: { maxWidth: 'infinity', alignment: 'leading' }, children: [
      { type: 'text', value: 'To-do', size: 15, weight: 'bold', color: '#FFFFFF', lineLimit: 1 },
      total > 0 && { type: 'text', value: d.finished + '/' + total, size: 12, color: '#9FB3C8',
        lineLimit: 1, minScale: 0.7 },
    ] },
    { type: 'button', action: 'add', children: [
      { type: 'symbol', name: 'plus.circle.fill', size: 20, color: '#7AE582' } ] },
  ] };

  return {
    type: 'vstack', align: 'leading', spacing: 6, padding: 14,
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
    widgetBackground: '#1E2A3A',
    children: [
      header,
      shown.length === 0 && { type: 'text', value: 'Nothing to do. Tap + to add one.', size: 13, color: '#9FB3C8' },
      { type: 'vstack', align: 'leading', spacing: small ? 2 : 4, children: shown.map(item => row(item, small ? 2 : 1)) },
    ],
  };
}
